import Header from "../components/Header";
import ProductButton from "../components/ProductButton";
import { certifications } from "../data/certifications";
import { products } from "../data/products";

export default function Home() {
  const visible = certifications.filter((cert) => cert.enabled);

  return (
    <main>
      <Header />

      <section className="hero shell homeHero">
        <p className="overline">IT CERTIFICATION SHORTEST GUIDE</p>
        <h1>何時間で、<br />取れる？</h1>
        <p className="heroText">
          IT資格の「合格までの最短目安」を先に見る。<br />
          教材はUdemy、詳しい根拠はnoteにまとめています。
        </p>
      </section>

      <section className="shell listSection">
        <div className="sectionHead">
          <p className="sectionTitle">最短時間から選ぶ</p>
          <span>{visible.length}資格</span>
        </div>

        <div className="certCards">
          {visible.map((cert) => {
            const primaryProduct = products[cert.productIds?.[0]];

            return (
              <article className="certCard" key={cert.slug}>
                <a className="certMain" href={`/${cert.slug}`}>
                  <div className="certNameLine">
                    <div>
                      <span className="category">{cert.category}</span>
                      <h2>{cert.name}</h2>
                    </div>
                    <span className="detailArrow">→</span>
                  </div>

                  <p className="timeLabel">最短合格目安</p>
                  <p className="timeValue">{cert.shortest}</p>
                  <p className="certSummary">{cert.summary}</p>
                </a>

                {primaryProduct && (
                  <div className="cardCta">
                    <ProductButton product={primaryProduct} certName={cert.name} />
                  </div>
                )}
              </article>
            );
          })}
        </div>
      </section>

      <section className="shell noteBlock">
        <p className="label">DETAILS ON NOTE</p>
        <p>なぜその時間なのか。合格者の事例や調査結果は各資格ページからnoteで確認できます。</p>
      </section>

      <footer className="footer shell">PRを含みます / © 2026 ponpokoken.com</footer>
    </main>
  );
}
